role {\"group\":\"Mannenklank Glanerbrug\",\"role\":\"contact\"}'),(14508,'2016-10-28 18:50:46','group-21',8,'82.74.227.245','delete role {\"person\":\"Wim Simmelink\",\"role\":\"treasurer\"}'),(14514,'2016-10-28 18:50:46','person-1034',8,'82.74.227.245','delete role {\"group\":\"Mannenklank Glanerbrug\",\"role\":\"treasurer\"}'),(14520,'2016-10-28 18:51:48','group-21',8,'82.74.227.245','change {\"city\":\"\",\"website\":\"\",\"description\":\"\",\"bankaccount\":\"\"}'),(14526,'2016-10-28 18:55:21','group-371',8,'82.74.227.245','change {\"website\":\"http:\\/\\/www.germaniakoor.nl\",\"description\":\"Hallo,\\r\\n\\r\\nOns koor is opgericht in 2004. Het koor bestaat uit 28 personen. Bas, Tenor en barritons. Begeleiding keyboard.\\r\\n\\r\\nDirigente zingt ook wel eens nummers mee. We beschikken over een eigen geluidsinstallatie. Ook hebben we een door ons zelf ontworpen muziektent. Ons repetoire bestaat uit oud Hollands maar ook vooral moderne liederen\"}'),(14532,'2016-10-28 19:02:09','group-219',8,'82.74.227.245','add role {\"person\":\"Rob Zieverink\",\"role\":\"conductor\"}'),(14538,'2016-10-28 19:02:09','person-24',8,'82.74.227.245','add role {\"group\":\"Markelo\'s Mannenkoor\",\"role\":\"conductor\"}'),(14544,'2016-10-28 19:02:15','group-219',8,'82.74.227.245','delete role {\"person\":\"Henk Swart\",\"role\":\"conductor\"}'),(14550,'2016-10-28 19:02:15','person-259',8,'82.74.227.245','delete role {\"group\":\"Markelo\'s Mannenkoor\",\"role\":\"conductor\"}'),(14556,'2016-10-28 19:06:26','group-773',8,'82.74.227.245','change {\"genre\":\"1\",\"website\":\"http:\\/\\/www.martinikoor.nl\\/\"}'),(14562,'2016-10-28 19:07:17','group-773',8,'82.74.227.245','add role {\"person\":\"Paul Kempers\",\"role\":\"conductor\"}'),(14568,'2016-10-28 19:07:17','person-3190',8,'82.74.227.245','add role {\"group\":\"Martinikoor Losser\",\"role\":\"conductor\"}'),(14574,'2016-10-28 19:07:22','group-773',8,'82.74.227.245','change {\"description\":\"Home\\r\\nHet Martinikoor is een zeer gerenommeerd mannenkoor uit Twente met als thuisbasis Losser. Het koor heeft ruim 30 actieve zangers en staat sinds 2001 onder leiding van de veelzijdige musicus en dirigent Paul Kempers. Het koor treedt gemiddeld 10 keer per jaar op, in Twente, maar ook daarbuiten en met regelmaat in Duitsland. In 2013 vierde het Martinikoor zijn 50-jarig jubileum. In 2014 wist het koor de eerste prijs te behalen in de C-klasse van het landelijk Mannenkoor Concours dat werd georganiseerd door het Koninklijk Nederlands Zangers Verbond.\\r\\n\\r\\nHet koor heeft een veelzijdig repertoire en zingt zowel klassiek, als modern. Van Russisch Byzantijns naar vlotte Barbershop-songs. Hoewel het Martinikoor geen kerkkoor is staat er ook kerkelijke muziek op het programma.\\r\\nIn het jubileumjaar 2013 heeft het Martinikoor een CD uitgebracht, delen daarvan zijn verder op deze site te beluisteren.\\r\\nWilt u meer informatie over ons koor of eventuele medewerking aan een festiviteit of concert, neem dan contact met ons op via de informatie op de contact pagina\"}'),(14580,'2016-10-28 19:07:53','person-2980',8,'82.74.227.245','change {\"firstname\":\"Frans\"}'),(14586,'2016-10-28 19:11:48','group-924',8,'82.74.227.245','change {\"genre\":\"1\",\"website\":\"http:\\/\\/www.meezingkoor-maassluis.nl\\/\"}'),(14592,'2016-10-28 19:14:52','person-1160',8,'82.74.227.245','change {\"email\":\"\"}'),(14598,'2016-10-28 19:23:44','person-1427',8,'82.74.227.245','change {\"email\":\"contact@barbaralok.nl\"}'),(14604,'2016-10-28 19:24:13','group-418',8,'82.74.227.245','delete role {\"person\":\"Alexandra Winter\",\"role\":\"treasurer\"}'),(14610,'2016-10-28 19:24:13','person-1337',8,'82.74.227.245','delete role {\"group\":\"Lok & Lol\",\"role\":\"treasurer\"}'),(14616,'2016-10-28 19:24:35','person-1337',8,'82.74.227.245','change {\"firstname\":\"Wilma\",\"lastname\":\"Holweg\",\"address\":\"\",\"zipcode\":\"\",\"city\":\"\",\"phone1\":\"\"}'),(14622,'2016-10-28 19:44:38','group-211',8,'82.74.227.245','