'/login.php\r\nsuccess'),(16236,'2016-10-31 18:25:14','group-400',8,'82.74.227.245','delete role {\"person\":\"Marianne Klumpes\",\"role\":\"treasurer\"}'),(16242,'2016-10-31 18:25:14','person-1303',8,'82.74.227.245','delete role {\"group\":\"CARAJILLO\",\"role\":\"treasurer\"}'),(16248,'2016-10-31 18:26:04','group-400',8,'82.74.227.245','change {\"city\":\"\",\"website\":\"\",\"description\":\"\",\"bankaccount\":\"\"}'),(16254,'2016-10-31 18:28:44','group-185',8,'82.74.227.245','change {\"description\":\"Muziektheater Capriccio\\u201997 uit Borne Overijssel is een dynamisch theaterkoor dat is opgericht in 1997. De vereniging bestaat uit een club enthousiaste leden die regelmatig optreden en elke woensdagavond repeteren in het Kulturhus in Borne. Een optreden is soms een grote productie maar kan ook een eenmalig optreden zijn in de vorm van een theatershow op maat bij bijvoorbeeld kleinere (theater)zalen, restaurants, hotels of tehuizen. Het repertoire is zeer divers en bestaat uit (delen van) musicals, popmuziek, themamuziek en operettes. Bij elk optreden zijn alle details, zoals decor, kostuums, zang, toneelspel en begeleiding tot in de puntjes verzorgd wat telkens weer een aangename verrassing is voor het publiek.\"}'),(16260,'2016-10-31 18:32:39','group-802',8,'82.74.227.245','delete role {\"person\":\"Inger Heij\",\"role\":\"conductor\"}'),(16266,'2016-10-31 18:32:39','person-3148',8,'82.74.227.245','delete role {\"group\":\"Vrouwenpopkoor Nenoni\",\"role\":\"conductor\"}'),(16272,'2016-10-31 18:36:15','person-675',8,'82.74.227.245','change {\"mailing\":false}'),(16278,'2016-10-31 18:40:50','login',8,'82.74.227.245','/login.php\r\nsuccess'),(16284,'2016-10-31 18:57:22','group-732',8,'82.74.227.245','change {\"genre\":\"1\",\"website\":\"http:\\/\\/www.watzup.nl\\/\"}'),(16290,'2016-10-31 19:19:49','person-1141',8,'82.74.227.245','change {\"email\":\"secretariaat@popkoorzinder.nl\",\"phone1\":\"0630590784\"}'),(16296,'2016-10-31 19:21:31','person-1369',8,'82.74.