}'),(38995,'2023-02-12 14:58:39','group-804',3150,'2001:1c01:2c16:8500:e954:3221:c671:2489','delete role {\"person\":\"Remco Broesder\",\"role\":\"conductor\"}'),(38996,'2023-02-12 14:59:32','group-804',3150,'2001:1c01:2c16:8500:e954:3221:c671:2489','request role add {\"person\":\"Arjen Kone\",\"role\":\"treasurer\",\"messageid\":\"<kDtEQ6Ud08iuvIkOyQNPeUAqPHeSa5HeuneUBrON8XI@amusing.nl>\",\"mailid\":\"2080A1817\"}'),(38997,'2023-02-12 17:28:17','login',9,'2a02:a44b:b5ed:1:9097:b73f:9bbf:7f6b','success'),(38998,'2023-02-12 21:20:48','login',8,'2a02:a440:f90e:1:2df7:a704:5e10:5a4a','success'),(38999,'2023-02-12 21:54:59','person-6163',6163,'2001:1c01:31c9:3600:5d03:86a7:344a:ca92','changed {\"firstname\":\"Petra\",\"prefix\":\"\",\"lastname\":\"Kuik\",\"phone\":\"0651522815\"}'),(39000,'2023-02-13 09:18:03','login',9,'212.102.33.212','success'),(39001,'2023-02-13 09:40:00','login',11,'82.75.139.22','success'),(39002,'2023-02-13 10:39:28','login',11,'82.75.139.22','success'),(39003,'2023-02-14 13:43:43','login',9,'84.241.194.255','success'),(39004,'2023-02-14 15:58:36','login',14,'77.173.249.59','success'),(39005,'2023-02-14 16:00:44','group-728',14,'77.173.249.59','add role {\"person\":\"Petra Kuik\",\"role\":\"contact\"}'),(39006,'2023-02-14 16:00:44','person-6163',14,'77.173.249.59','add role {\"group\":\"Popkoor Roll the Voices\",\"role\":\"contact\"}'),(39007,'2023-02-14 16:08:37','login',9,'212.102.33.159','success'),(39008,'2023-02-15 07:33:55','login',8,'2a02:a440:f90e:1:b6e3:595a:a4f9:fe8e','success'),(39009,'2023-02-15 15:26:16','login',14,'77.173.249.59','success'),(39010,'2023-02-15 15:52:36','group-181',6164,'145.131.180.137','changed {\"name\":\"Koninklijk Hengelo\'s Mannenkoor (KHM)\",\"genre\":\"9\",\"city\":\"Hengelo\",\"country\":\"nl\",\"website\":\"www.khmk.nl\",\"email\":\"uitklep@gmail.com\",\"photo\":\"...\",\"logo\":\"...\",\"description\":\"Het Koninklijk Hengelo\\u2019s Mannenkoor is opgericht in 1886 en mag terecht groot heten. Ruim 60 zangers laten enthousiast en 4-stemmig van zich horen. Ons koor zingt een afwisselend repertoire. In het verleden was dat nogal eens het wat \\u2018zwaardere\\u2019 werk, tegenwoordig hebben we een heel arsenaal aan vlotte en meer moderne nummers. Niet alleen ons publiek weet dat te waarderen, ook onze zangers zijn hier blij mee.\\r\\n\\r\\nSommige nummers klinken het mooist a capella, andere nummers worden begeleid door onze pianist. Hier en daar speelt er zelfs een extra instrument mee... variatie genoeg!\\r\\n\\r\\nLaat je eens verrassen en kom een keertje meezingen! Neem hiervoor contact op met Rinus Gerritsjans, tel. 074-2771957  \\r\\nHij zorgt er voor dat er materiaal voor je klaar ligt zodat je niet met je mond vol tanden staat... \\r\\n\\r\\nHet KHM staat onder de professionele leiding van dirigent Jacco Camphens, vaste begeleider op de vleugel is Wouter Munsterman.\"}'),(39011,'2023-02-15 15:53:36','group-181',6164,'145.131.180.137','changed {\"name\":\"Koninklijk Hengelo\'s Mannenkoor (KHM)\",\"genre\":\"9\",\"city\":\"Hengelo\",\"country\":\"nl\",\"website\":\"www.khmk.nl\",\"email\":\"uitklep@gmail.com\",\"photo\":\"...\",\"logo\":\"...\",\"description\":\"Het Koninklijk Hengelo\\u2019s Mannenkoor is opgericht in 1886 en mag terecht groot heten. Ruim 60 zangers laten enthousiast en 4-stemmig van zich horen. Ons koor zingt een afwisselend repertoire. In het verleden was dat nogal eens het wat \\u2018zwaardere\\u2019 werk, tegenwoordig hebben we een heel arsenaal aan vlotte en meer moderne nummers. Niet alleen ons publiek weet dat te waarderen, ook onze zangers zijn hier blij mee.\\r\\n\\r\\nSommige nummers klinken het mooist a capella, andere nummers worden begeleid door onze pianist. Hier en daar speelt er zelfs een extra instrument mee... variatie genoeg!\\r\\n\\r\\nLaat je eens verrassen en kom een keertje meezingen! We repeteren elke donderdagavond van 20:00-22:00 uur bij Oyfo. Stap vrijblijvend binnen en proef de informele sfeer en hartelijkheid. Een afspraak maken is niet nodig, wij vangen je wel op. Heb je liever even contact, bel dan met Marius Uiterwijk, 06-36325163. \\r\\nHij zorgt er voor dat er materiaal voor je klaar ligt zodat je niet met je mond vol tanden staat... \\r\\nHet KHM staat onder de professionele leiding van dirigent Jacco Camphens, vaste begeleider op de vleugel is Wouter Munsterman.\"}'),(39012,'2023-02-15 15:53:57','group-181',6164,'145.131.180.137','changed {\"name\":\"Koninklijk Hengelo\'s Mannenkoor (KHM)\",\"genre\":\"9\",\"city\":\"Hengelo\",\"country\":\"nl\",\"website\":\"www.khmk.nl\",\"email\":\"uitklep@gmail.com\",\"photo\":\"...\",\"logo\":\"...\",\"description\":\"Het Koninklijk Hengelo\\u2019s Mannenkoor is opgericht in 1886 en mag terecht groot heten. Ruim 60 zangers laten enthousiast en 4-stemmig van zich horen. Ons koor zingt een afwisselend repertoire. In het verleden was dat nogal eens het wat \\u2018zwaardere\\u2019 werk, tegenwoordig hebben we een heel arsenaal aan vlotte en meer moderne nummers. Niet alleen ons publiek weet dat te waarderen, ook onze zangers zijn hier blij mee.\\r\\n\\r\\nSommige nummers klinken het mooist a capella, andere nummers worden begeleid door onze pianist. Hier en daar speelt er zelfs een extra instrument mee... variatie genoeg!\\r\\n\\r\\nLaat je eens verrassen en kom een keertje meezingen! We repeteren elke donderdagavond van 20:00-22:00 uur bij Oyfo. Stap vrijblijvend binnen en proef de informele sfeer en hartelijkheid. Een afspraak maken is niet nodig, wij vangen je wel op. Heb je liever even contact, bel dan met Marius Uiterwijk, 06-36325163. \\r\\n\\r\\nHij zorgt er voor dat er materiaal voor je klaar ligt zodat je niet met je mond vol tanden staat... \\r\\n\\r\\nHet KHM staat onder de professionele leiding van dirigent Jacco Camphens, vaste begeleider op de vleugel is Wouter Munsterman.\"}'),(39013,'2023-02-15 15:54:57','group-181',6164,'145.131.180.137','enroll group {\n    \"festival\": \"18\",\n    \"group\": \"181\",\n    \"dressingr