CREATE TABLE `ah_inschrijvingen` (
  `festival_id` int unsigned NOT NULL DEFAULT '0',
  `zanggroep_id` int unsigned NOT NULL DEFAULT '0',
  `wens_1` enum('ja','nee') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'nee' COMMENT 'kleedruimte',
  `wens_2` enum('ja','nee') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'nee' COMMENT 'singalong',
  `wens_3` enum('ja','nee') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'nee' COMMENT 'stand',
  `wens_4` enum('ja','nee') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'nee' COMMENT 'beoordeling',
  `nfve` enum('ja','nee') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'nee',
  `afactor` enum('ja','nee') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'nee',
  `aantal_deelnemers` int unsigned NOT NULL DEFAULT '0',
