  `buitenoptredens` tinyint unsigned NOT NULL DEFAULT '1',
  `bevestigd` datetime DEFAULT NULL,
  PRIMARY KEY (`festival_id`,`zanggroep_id`),
  KEY `zanggroep_id` (`zanggroep_id`),
